create table if not exists feedback_clusters (id uuid primary key default gen_random_uuid(), title varchar(160) not null, summary varchar(1000) not null, confidence varchar(16) not null, status varchar(16) not null default 'active', model varchar(160) not null, provider varchar(80) not null, prompt_version varchar(80) not null, context_version varchar(80) not null, member_count integer not null, total_votes integer not null, last_analyzed_at timestamp not null, created_at timestamp not null default now(), updated_at timestamp not null default now());
create index if not exists idx_feedback_clusters_status on feedback_clusters(status);
create table if not exists feedback_cluster_members (cluster_id uuid not null references feedback_clusters(id) on delete cascade, feedback_id uuid not null references feedback_items(id) on delete cascade, similarity_score real, created_at timestamp not null default now(), primary key(cluster_id, feedback_id));
create index if not exists idx_feedback_cluster_members_feedback on feedback_cluster_members(feedback_id);
create table if not exists feedback_cluster_runs (id uuid primary key default gen_random_uuid(), requested_by_admin_id uuid not null references users(id), model varchar(160) not null, provider varchar(80) not null, prompt_version varchar(80) not null, context_version varchar(80) not null, context_hash varchar(128) not null, input_count integer not null, output_cluster_count integer not null, reused boolean not null default false, created_at timestamp not null default now());
create index if not exists idx_feedback_cluster_runs_context on feedback_cluster_runs(context_hash);
